/**
 * Die 23 Wiener Bezirke als SVG-Pfade.
 *
 * ⚠️ **Diese Datei ist ERZEUGT.** Nicht von Hand ändern —
 * `python3 scripts/bezirke-bauen.py` baut sie aus den amtlichen Grenzen neu.
 *
 * ── Quelle und Namensnennung ────────────────────────────────────────────────
 * Stadt Wien (data.wien.gv.at), Datensatz BEZIRKSGRENZEOGD, **CC BY 4.0**. Die
 * Nennung ist Bedingung der Lizenz und steht in der App unter der Karte —
 * `KARTE_QUELLE` in `features/posts/karte.ts`. Wer die Karte woanders einbaut,
 * nimmt die Zeile mit.
 *
 * ── Warum Daten und Zeichner getrennt liegen ────────────────────────────────
 * Dieselbe Bauart wie `theme/icons.ts`: Hier stehen nur Pfadstrings, gezeichnet
 * wird in `components/ui/SsWienKarte.tsx`, und was eine Farbe bedeutet, steht in
 * `features/posts/karte.ts`. Ein neuer Grenzverlauf ist damit ein Skriptlauf und
 * kein Screen.
 *
 * ── Wie genau das ist ───────────────────────────────────────────────────────
 * Aus 118683 amtlichen Stützpunkten sind 6252 geworden (5.3%) — auf
 * ein Raster von 0.05 Einheiten gerundet und mit Douglas-Peucker geglättet
 * (Toleranz 0.05). Eine Einheit des viewBox sind rund 20 m — ein
 * RASTERSCHRITT also 1.0 m, und die Abweichung der Grenze
 * höchstens **1.0 m**.
 *
 * ⚠️ **Diese Zahl ist gewählt, nicht geerbt.** Bis zum 2026-09-20 lag sie bei
 * 39,1 m, und Ian sah das beim Hineinzoomen als Zacken. Warum jetzt gerade
 * dieser Wert — und warum ein GRÖBERES Raster nichts spart — steht bei `RASTER`
 * in `scripts/bezirke-bauen.py`; nachmessen lässt es sich mit
 * `python3 scripts/bezirke-messen.py`. **Das ist die Messstelle dazu**, ohne
 * sie wäre die Zahl oben nicht reproduzierbar.
 *
 * **Das ist trotzdem eine Übersichtskarte, keine Vermessung** — sie beantwortet
 * „wo ist gerade etwas los", nicht „wo genau verläuft die Grenze".
 */

/** Ein Bezirk als Fläche. `plz` ist derselbe Wert wie `Post.district`. */
export interface BezirkFlaeche {
  /** "1010" — passt direkt auf `Post.district`. */
  plz: string;
  /** 1 bis 23. Das, was in der Fläche steht, wenn Platz ist. */
  nr: number;
  /** "Innere Stadt" */
  name: string;
  /**
   * Wo die Zahl hineinpasst — und wie viel Platz dort ist.
   *
   * `x`/`y` ist der Punkt mit dem größten Abstand zum Rand, `r` genau dieser
   * Abstand. **`r` ist kein Schmuck:** Die Josefstadt ist bei Handybreite 14 × 11
   * Bildpunkte groß, eine Zahl passt dort erst hinein, wenn jemand hineingezoomt
   * hat. Der Zeichner entscheidet daran, ob er sie überhaupt schreibt — Farbe
   * allein ist keine Auskunft (PLAN.md, Phase 19b, Punkt 2), eine Zahl, die über
   * ihre Fläche hinausragt, aber auch nicht.
   */
  label: { x: number; y: number; r: number };
  /** Der SVG-Pfad im Raster unten. */
  d: string;
}

/** Das Raster, in dem alle Pfade unten liegen. */
export const KARTE_BREITE = 1000;
export const KARTE_HOEHE = 776.7;

/**
 * Wie aus einer Rasterstelle wieder ein Ort auf der Erde wird.
 *
 * ── Warum vier Zahlen und nicht 886 Punkte ein zweites Mal ──────────────────
 * Seit Phase 19d gibt es einen ZWEITEN Zeichner: Auf iOS liegen die Bezirke als
 * Polygone auf einer echten Apple-Karte, und MapKit rechnet in Längen- und
 * Breitengraden. Die Umrisse oben stehen aber im Raster.
 *
 * Der naheliegende Weg wäre gewesen, die Geo-Punkte ZUSÄTZLICH zu speichern —
 * dieselben Punkte ein zweites Mal, in einer zweiten Einheit. Dann gäbe es zwei
 * Fassungen derselben Geometrie, und die zweite wäre die, die beim nächsten
 * Skriptlauf jemand vergisst. Dieselbe Überlegung wie bei `landing/stil.css`
 * (harte Regel 13), nur diesmal vermeidbar: Die Projektion ist eine flache
 * Rechnung mit Kosinus-Korrektur (Entscheidung 1 im Kopf des Skripts) und damit
 * **exakt umkehrbar**.
 *
 *     lon = lon0 + x / (k · massstab)
 *     lat = lat1 − y / massstab
 *
 * Gerechnet wird das in `lib/karte-geo.ts`; hier stehen nur die Zahlen, wie
 * überall in dieser Datei.
 */
export const PROJEKTION = {
  /** Westlichster Längengrad Wiens — der linke Rand des Rasters (x = 0). */
  lon0: 16.18183038,
  /** Nördlichster Breitengrad — der OBERE Rand (y = 0; y wächst nach unten). */
  lat1: 48.32266666,
  /** cos(mittlere Breite). Ohne ihn wäre Wien um 50 % zu breit. */
  k: 0.666268500065024,
  /** Rastereinheiten je Grad (nach der Kosinus-Korrektur). */
  massstab: 3793.171719168709,
};

